def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 4:
        return 'C'
    opp = [h[1] for h in history]
    last_opp = opp[-1]
    last_me = history[-1][0]
    opp_d = 0
    for b in opp:
        if b == 'D':
            opp_d += 1
    if opp_d == 0:
        if n >= 95:
            return 'D'
        return 'C'
    streak_d = 0
    for b in reversed(opp):
        if b == 'D':
            streak_d += 1
        else:
            break
    streak_c = 0
    for b in reversed(opp):
        if b == 'C':
            streak_c += 1
        else:
            break
    if last_opp == 'D':
        if last_me == 'D':
            if streak_d >= 6:
                return 'C' if rng.random() < 0.22 else 'D'
            if n >= 3 and opp[-2] == 'C' and opp[-1] == 'D' and history[-2][0] == 'C':
                return 'D'
            if streak_d >= 3:
                return 'D'
            if rng.random() < 0.3:
                return 'C'
            return 'D'
        else:
            if opp_d >= n - 1:
                return 'D'
            if streak_d >= 2:
                return 'D'
            return 'D'
    if streak_c >= 2:
        if n >= 98:
            return 'D'
        if opp_d * 5 <= n:
            if n >= 88 and rng.random() < 0.35:
                return 'D'
            return 'C'
        if opp_d * 2 <= n:
            if rng.random() < 0.06:
                return 'D'
            return 'C'
        if opp_d * 3 >= n * 2:
            return 'D'
        return 'D' if rng.random() < 0.7 else 'C'
    if opp_d * 4 <= n:
        if n >= 96:
            return 'D'
        return 'C'
    if opp_d * 3 >= n * 2:
        if rng.random() < 0.08:
            return 'C'
        return 'D'
    if last_me == 'D':
        if opp[-1] == 'C' and opp_d * 3 <= n * 2:
            return 'C'
        return 'D'
    if rng.random() < 0.15:
        return 'D'
    return 'C'
